// Which prompts count as a task. One typed request is one task: a prompt the
// person typed (or sent from the phone, or a mod sent as their own words)
// that goes on to finish with an answer. Pure; register.tsx wires it to events.

export type Origin = { kind: string; asUser?: boolean | undefined }

/** `/compact`, `/report week`: a slash command, as against a path that happens to start with one. */
export function isSlashCommand(text: string): boolean {
  const first = text.trimStart().split(/\s+/)[0] ?? ''
  return /^\/[A-Za-z][\w:.-]*$/.test(first)
}

/**
 * Whether a submitted prompt is the person's own request. Their Enter at the
 * prompt and a message from the phone count. A mod's prompt counts only when
 * it sent the words as the person's own (an upgraded prompt they approved).
 * Background notifications, schedules, other sessions, helper agents and
 * `claude -p` runs are not requests anyone typed.
 */
export function isTypedPrompt(text: string, origin: Origin): boolean {
  if (text.trim() === '') return false
  if (isSlashCommand(text)) return false
  if (origin.kind === 'composer' || origin.kind === 'bridge') return true
  return origin.kind === 'plugin' && origin.asUser === true
}

// A typed prompt is "armed" when it is submitted and claimed when a turn
// starts with those words, so a turn nobody typed is never counted.

const LIMIT = 20

const same = (a: string, b: string) => a.trim() === b.trim()

export function arm(queue: readonly string[], text: string): string[] {
  return [...queue, text].slice(-LIMIT)
}

export function disarm(queue: readonly string[], text: string): string[] {
  const at = queue.findIndex(q => same(q, text))
  return at < 0 ? [...queue] : [...queue.slice(0, at), ...queue.slice(at + 1)]
}

/**
 * Takes the armed prompt a turn started with off the queue. The words match
 * exactly, or, where something added to them on the way in (a settings hook's
 * note), when one holds the other and is long enough not to be a coincidence.
 */
export function claim(queue: readonly string[], turnText: string): { found: boolean; queue: string[] } {
  const exact = queue.findIndex(q => same(q, turnText))
  const near = exact >= 0 ? exact : queue.findIndex(q => {
    const a = q.trim()
    const b = turnText.trim()
    const [short, long] = a.length <= b.length ? [a, b] : [b, a]
    return short.length >= 8 && long.includes(short)
  })
  if (near < 0) return { found: false, queue: [...queue] }
  return { found: true, queue: [...queue.slice(0, near), ...queue.slice(near + 1)] }
}

files.hooks/report.ts:
// The numbers: day records, totals over a stretch, the estimate, the streak
// and the chart's bars. Pure; register.tsx reads and writes the store.
import type { DayRecord, Kind, Settings, Tab } from '../types'
import { addDays, keyOf, lastDays, MONTHS, MONTHS_LONG, noonOf, WEEKDAYS } from './dates'
import { KINDS } from './kinds'

// ── Day records ──────────────────────────────────────────────────────────

export const emptyDay = (): DayRecord => ({ kinds: {}, models: {} })

const count = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) && v > 0 ? Math.floor(v) : 0)

/** A record as the store gave it back, made safe: unknown keys and bad numbers are dropped. */
export function normalizeDay(raw: unknown): DayRecord {
  const out = emptyDay()
  if (!raw || typeof raw !== 'object') return out
  const r = raw as { kinds?: unknown; models?: unknown }
  if (r.kinds && typeof r.kinds === 'object') {
    for (const k of KINDS) {
      const n = count((r.kinds as Record<string, unknown>)[k])
      if (n > 0) out.kinds[k] = n
    }
  }
  if (r.models && typeof r.models === 'object') {
    for (const [name, v] of Object.entries(r.models as Record<string, unknown>)) {
      const n = count(v)
      if (n > 0) out.models[name] = n
    }
  }
  return out
}

/** How many tasks a day holds. */
export function tasksOf(rec: DayRecord | undefined): number {
  if (!rec) return 0
  return KINDS.reduce((n, k) => n + (rec.kinds[k] ?? 0), 0)
}

/** Two days added together: the counts of each kind and of each model summed. */
export function mergeDays(a: DayRecord, b: DayRecord): DayRecord {
  const out = emptyDay()
  for (const k of KINDS) {
    const n = (a.kinds[k] ?? 0) + (b.kinds[k] ?? 0)
    if (n > 0) out.kinds[k] = n
  }
  for (const src of [a.models, b.models]) {
    for (const [name, n] of Object.entries(src)) out.models[name] = (out.models[name] ?? 0) + n
  }
  return out
}

/** One more task on a day. */
export function addTask(rec: DayRecord, kind: Kind, model: string): DayRecord {
  return mergeDays(rec, { kinds: { [kind]: 1 }, models: { [model]: 1 } })
}

// ── Totals ───────────────────────────────────────────────────────────────

export type Totals = {
  tasks: number
  kinds: Record<Kind, number>
  models: Record<string, number>
  /** Tasks on each of the given days, in order. */
  perDay: number[]
}

/** The days of `keys` added together. */
export function totalsFor(days: Readonly<Record<string, DayRecord>>, keys: readonly string[]): Totals {
  let sum = emptyDay()
  const perDay: number[] = []
  for (const key of keys) {
    const rec = days[key]
    perDay.push(tasksOf(rec))
    if (rec) sum = mergeDays(sum, rec)
  }
  const kinds = {} as Record<Kind, number>
  for (const k of KINDS) kinds[k] = sum.kinds[k] ?? 0
  return { tasks: KINDS.reduce((n, k) => n + kinds[k], 0), kinds, models: sum.models, perDay }
}

/**
 * The kinds a stretch has tasks of, most first. `other` is the catch-all and
 * stays last however many it holds; a tie keeps the order of KINDS.
 */
export function shownKinds(kinds: Readonly<Record<Kind, number>>): Kind[] {
  const used = KINDS.filter(k => (kinds[k] ?? 0) > 0)
  const named = used.filter(k => k !== 'other').sort((a, b) => (kinds[b] ?? 0) - (kinds[a] ?? 0))
  return used.includes('other') ? [...named, 'other'] : named
}

// ── The estimate ─────────────────────────────────────────────────────────

export const DEFAULT_SETTINGS: Settings = {
  rate: 50,
  minutes: { emails: 10, documents: 30, images: 20, code: 20, research: 20, other: 10 },
  band: true,
}

/** Settings as the store gave them back, each value checked, the rest the default. */
export function normalizeSettings(raw: unknown): Settings {
  const out: Settings = { rate: DEFAULT_SETTINGS.rate, minutes: { ...DEFAULT_SETTINGS.minutes }, band: DEFAULT_SETTINGS.band }
  if (!raw || typeof raw !== 'object') return out
  const r = raw as { rate?: unknown; minutes?: unknown; band?: unknown }
  if (typeof r.rate === 'number' && Number.isFinite(r.rate) && r.rate >= 0) out.rate = r.rate
  if (typeof r.band === 'boolean') out.band = r.band
  if (r.minutes && typeof r.minutes === 'object') {
    for (const k of KINDS) {
      const v = (r.minutes as Record<string, unknown>)[k]
      if (typeof v === 'number' && Number.isFinite(v) && v >= 0) out.minutes[k] = v
    }
  }
  return out
}

export type Estimate = {
  minutes: number
  hours: number
  dollars: number
  /** Minutes and hours of each kind, for the rows. */
  byKind: Record<Kind, { minutes: number; hours: number }>
}

export function estimate(kinds: Readonly<Record<Kind, number>>, settings: Settings): Estimate {
  const byKind = {} as Estimate['byKind']
  let minutes = 0
  for (const k of KINDS) {
    const m = (kinds[k] ?? 0) * settings.minutes[k]
    byKind[k] = { minutes: m, hours: m / 60 }
    minutes += m
  }
  const hours = minutes / 60
  return { minutes, hours, dollars: hours * settings.rate, byKind }
}

// ── Streak, best day, best month ─────────────────────────────────────────

/**
 * Days in a row with at least one task, counted back from today. A day that
 * has not had its first task yet does not break the streak: it counts from
 * yesterday until today has one.
 */
export function streak(days: Readonly<Record<string, DayRecord>>, ms: number): number {
  let cursor = noonOf(ms)
  if (tasksOf(days[keyOf(cursor)]) === 0) cursor = addDays(cursor, -1)
  let n = 0
  while (n < 3700 && tasksOf(days[keyOf(cursor)]) > 0) {
    n += 1
    cursor = addDays(cursor, -1)
  }
  return n
}

// ── The chart ────────────────────────────────────────────────────────────

export type Bar = {
  /** What stands under the bar; empty when this bar carries none. */
  label: string
  value: number
  /** Today, or this month: drawn in gold. */
  isCurrent: boolean
  /** A month that has not come yet: drawn empty. */
  isFuture: boolean
}

/** Tasks in each month of `year`, January first. */
export function monthTotals(days: Readonly<Record<string, DayRecord>>, year: number): number[] {
  const out = new Array<number>(12).fill(0)
  const prefix = `${year}-`
  for (const [key, rec] of Object.entries(days)) {
    if (!key.startsWith(prefix)) continue
    const m = Number(key.slice(5, 7)) - 1
    if (m >= 0 && m < 12) out[m] = (out[m] ?? 0) + tasksOf(rec)
  }
  return out
}

/**
 * The bars a tab draws. Today and Week: the last seven days by weekday. Month:
 * thirty daily bars. Year: January through December, this month current and
 * the months to come empty.
 */
export function chartFor(tab: Tab, days: Readonly<Record<string, DayRecord>>, ms: number): Bar[] {
  if (tab === 'today' || tab === 'week') {
    return lastDays(ms, 7).map((d, i, all) => ({
      label: WEEKDAYS[d.getDay()] ?? '',
      value: tasksOf(days[keyOf(d)]),
      isCurrent: i === all.length - 1,
      isFuture: false,
    }))
  }
  if (tab === 'month') {
    return lastDays(ms, 30).map((d, i, all) => ({
      // every fifth date, and today, carry their number
      label: d.getDate() % 5 === 0 || i === all.length - 1 ? String(d.getDate()) : '',
      value: tasksOf(days[keyOf(d)]),
      isCurrent: i === all.length - 1,
      isFuture: false,
    }))
  }
  const today = noonOf(ms)
  const totals = monthTotals(days, today.getFullYear())
  return MONTHS.map((name, m) => ({
    label: name,
    value: totals[m] ?? 0,
    isCurrent: m === today.getMonth(),
    isFuture: m > today.getMonth(),
  }))
}

export type Summary = {
  text: string
  /** The same in fewer words, for a narrow pane. */
  short: string
  isGood: boolean
}

/** The one line under the chart. */
export function summaryFor(tab: Tab, days: Readonly<Record<string, DayRecord>>, ms: number): Summary {
  if (tab === 'today' || tab === 'week') {
    const n = streak(days, ms)
    if (n === 0) return { text: 'No streak yet. Finish a task today to start one.', short: 'No streak yet', isGood: false }
    return { text: `Streak: ${n} ${n === 1 ? 'day' : 'days'} in a row.`, short: `Streak: ${n} ${n === 1 ? 'day' : 'days'}`, isGood: true }
  }
  if (tab === 'month') {
    const span = lastDays(ms, 30)
    const per = span.map(d => tasksOf(days[keyOf(d)]))
    const active = per.filter(n => n > 0).length
    let best = -1
    per.forEach((n, i) => {
      if (n > 0 && (best < 0 || n > (per[best] ?? 0))) best = i
    })
    const day = best >= 0 ? span[best] : undefined
    if (!day) return { text: `Best day: none yet. 0 active days of ${span.length}.`, short: '0 active days', isGood: false }
    const dayText = `${WEEKDAYS[day.getDay()]} ${day.getDate()} ${MONTHS[day.getMonth()]}`
    const n = per[best] ?? 0
    return {
      text: `Best day: ${dayText}, ${n} ${n === 1 ? 'task' : 'tasks'}. ${active} active ${active === 1 ? 'day' : 'days'} of ${span.length}.`,
      short: `Best ${day.getDate()} ${MONTHS[day.getMonth()]} (${n}), ${active} active`,
      isGood: true,
    }
  }
  const today = noonOf(ms)
  const totals = monthTotals(days, today.getFullYear())
  let bestMonth = -1
  totals.forEach((n, m) => {
    if (n > 0 && (bestMonth < 0 || n > (totals[bestMonth] ?? 0))) bestMonth = m
  })
  let active = 0
  const prefix = `${today.getFullYear()}-`
  for (const [key, rec] of Object.entries(days)) if (key.startsWith(prefix) && tasksOf(rec) > 0) active += 1
  if (bestMonth < 0) return { text: 'Best month: none yet. 0 active days.', short: '0 active days', isGood: false }
  const n = totals[bestMonth] ?? 0
  return {
    text: `Best month: ${MONTHS_LONG[bestMonth]}, ${n} ${n === 1 ? 'task' : 'tasks'}. ${active} active ${active === 1 ? 'day' : 'days'}.`,
    short: `Best ${MONTHS[bestMonth]} (${n}), ${active} active`,
    isGood: true,
  }
}

// ── Names ────────────────────────────────────────────────────────────────

/** "claude-sonnet-5-5" is "Sonnet 5.5"; an id this does not know is shown as it came, less its date. */
export function modelName(id: string | undefined): string {
  if (!id) return 'Unknown model'
  const clean = id.replace(/\[[^\]]*\]$/, '').trim()
  // claude-sonnet-5-5, claude-opus-4-1-20250805, claude-sonnet-4-20250514
  const family = /claude-(opus|sonnet|haiku|fable)-(\d+)(?:-(\d{1,2})(?!\d))?/.exec(clean)
  // claude-3-5-sonnet-20241022
  const old = /claude-(\d+)(?:-(\d{1,2})(?!\d))?-(opus|sonnet|haiku)/.exec(clean)
  const make = (name: string, major: string, minor?: string) => `${name.charAt(0).toUpperCase()}${name.slice(1)} ${major}${minor ? `.${minor}` : ''}`
  if (family) return make(family[1] ?? '', family[2] ?? '', family[3])
  if (old) return make(old[3] ?? '', old[1] ?? '', old[2])
  const bare = clean.replace(/^claude-/, '').replace(/-\d{8}$/, '')
  return bare === '' ? 'Unknown model' : bare
}

// ── Numbers as words ─────────────────────────────────────────────────────

/** "2.5" under ten hours, a whole number from there. */
export function hoursText(hours: number): string {
  if (!(hours > 0)) return '0'
  if (hours < 10) {
    const t = (Math.round(hours * 10) / 10).toFixed(1)
    return t.endsWith('.0') ? t.slice(0, -2) : t
  }
  return String(Math.round(hours))
}

/** 1234567 is "1,234,567". */
export function withCommas(n: number): string {
  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

files.hooks/view.tsx:
// The pane, drawn from what the state holds. Nothing here writes: a press
// calls one of the actions register.tsx hands in.
//
// Every row is sized to the width the pane reports, in cells, so nothing wraps:
// text is chosen from wordings that fit, bars and the chart are built to the
// width, and a row is clipped at the edge rather than wrapped should a surface
// be narrower than it said.
import type { Elements, UiPressArgument } from 'claude-code'

import type { DayRecord, Kind, Settings, Tab } from '../types'
import { daysFor, describeDays, keyOf, sinceWords, stretchName, TAB_NAME } from './dates'
import { KIND_LABEL, KIND_SHORT, KINDS } from './kinds'
import { barRow, chartPlan, clip, COLORS, fit, KIND_TONE, padStart, strWidth, tileFace, tilePlan, TITLE } from './layout'
import type { Line, Tone } from './layout'
import { chartFor, estimate, hoursText, shownKinds, summaryFor, totalsFor, withCommas } from './report'
import { barsSvg, chartSvg, drawingWidth, tilesSvg } from './svg'

type El = Elements['terminal']
type SvgEl = Elements['desktop']['Svg']
type Press = (e: UiPressArgument) => void

export type Actions = {
  pickTab: (tab: Tab) => void
}

export type Model = {
  /** What the pane reports it is wide, in cells. */
  width: number
  tab: Tab
  days: Readonly<Record<string, DayRecord>>
  settings: Settings
  /** Now, in milliseconds. */
  now: number
  /**
   * The vector element, where the surface draws one (the desktop, the editor):
   * the tiles, bars and chart are then drawings, which no font can put out of
   * line. Absent on the terminal, which draws them as text.
   */
  Svg?: SvgEl
}

// Far more glyphs than any pane is wide: the box around it clips the rest
const RUN = 400
const TABS: readonly { tab: Tab; hotkey: string }[] = [
  { tab: 'today', hotkey: 't' },
  { tab: 'week', hotkey: 'w' },
  { tab: 'month', hotkey: 'm' },
  { tab: 'year', hotkey: 'y' },
]

// ── Pieces ───────────────────────────────────────────────────────────────

/** One row of coloured segments, at most one line tall: clipped at the edge, never wrapped. */
function lineRow(el: El, line: Line) {
  const { Box, Text } = el
  const segs = line.filter(s => s.t !== '')
  if (segs.length === 0) return <Text> </Text>
  return (
    <Box flexDirection="row" width="100%" height={1} overflow="hidden">
      {segs.map(s => (
        <Text color={COLORS[s.tone]} {...(s.bold ? { bold: true } : {})}>
          {s.t}
        </Text>
      ))}
    </Box>
  )
}

const blank = (el: El) => lineRow(el, [])

/** A rule that fills what is left of its row: clipped at the edge, never wrapped. */
function rule(el: El, color: string = COLORS.hair, glyph = '─') {
  const { Box, Text } = el
  return (
    <Box flexGrow={1} flexShrink={1} minWidth={0} height={1} overflow="hidden">
      <Text color={color}>{glyph.repeat(RUN)}</Text>
    </Box>
  )
}

/** SMALL MUTED CAPITALS with a note at the far end, and a hairline under them across the pane. */
function heading(el: El, width: number, label: string, right?: string) {
  const { Box, Text } = el
  const note = right ? clip(right, Math.max(0, width - strWidth(label) - 2)) : ''
  return (
    <Box flexDirection="column" width="100%">
      <Box flexDirection="row" justifyContent="space-between" width="100%" columnGap={2}>
        <Box flexShrink={0}>
          <Text color={COLORS.muted}>{label.toUpperCase()}</Text>
        </Box>
        {note !== '' ? (
          <Box flexShrink={1}>
            <Text color={COLORS.muted}>{note}</Text>
          </Box>
        ) : null}
      </Box>
      <Box flexDirection="row" width="100%">
        {rule(el)}
      </Box>
    </Box>
  )
}

function chip(el: El, o: { key: string; label: string; isMain: boolean; hotkey: string; onPress: Press }) {
  const { Button, Text } = el
  const look = o.isMain
    ? { backgroundColor: COLORS.gold, color: COLORS.dark, bold: true }
    : { backgroundColor: COLORS.hair, color: COLORS.text }
  return (
    <Button key={o.key} plain hotkey={o.hotkey} onPress={o.onPress}>
      <Text {...look}>{` ${o.label} `}</Text>
    </Button>
  )
}

/** The title in bold capitals, a gold rule the width of the title that carries on as a hairline. */
function top(el: El) {
  const { Box, Text } = el
  return [
    <Box flexDirection="row" width="100%">
      <Text bold color={COLORS.text}>
        {TITLE}
      </Text>
    </Box>,
    <Box flexDirection="row" width="100%">
      <Box flexShrink={0}>
        <Text color={COLORS.gold}>{'━'.repeat(TITLE.length)}</Text>
      </Box>
      {rule(el)}
    </Box>,
  ]
}

/** The stretch on the left, its dates on the right, a hairline under. */
function titleBar(el: El, width: number, left: string, right: string) {
  const { Box, Text } = el
  const l = clip(left, width)
  const r = fit(Math.max(0, width - strWidth(l) - 2), [right, right.replace(/ \d{4}$/, ''), ''])
  return (
    <Box flexDirection="column" width="100%">
      <Box flexDirection="row" justifyContent="space-between" width="100%" columnGap={2}>
        <Box flexShrink={0}>
          <Text bold color={COLORS.text}>
            {l.toUpperCase()}
          </Text>
        </Box>
        {r !== '' ? (
          <Box flexShrink={1}>
            <Text color={COLORS.muted}>{r}</Text>
          </Box>
        ) : null}
      </Box>
      <Box flexDirection="row" width="100%">
        {rule(el)}
      </Box>
    </Box>
  )
}

// ── Sections ─────────────────────────────────────────────────────────────

function tilesBlock(el: El, width: number, tasks: number, hours: number, dollars: number, Svg?: SvgEl) {
  const { Box, Text } = el
  const plan = tilePlan(width)
  const hoursNum = hoursText(hours)
  const dollarsNum = String(Math.round(dollars))
  const tiles: { id: string; numerals: string; plain: string; tone: Tone; captions: string[] }[] = [
    { id: 'hours', numerals: hoursNum, plain: `${hoursNum} h`, tone: 'gold', captions: ['est. hours saved', 'est. hours', 'hours'] },
    { id: 'tasks', numerals: String(tasks), plain: withCommas(tasks), tone: 'text', captions: ['tasks done', 'tasks'] },
    { id: 'worth', numerals: dollarsNum, plain: `$${withCommas(dollars)}`, tone: 'green', captions: ['est. worth in $', 'est. $', '$'] },
  ]
  const shown = tiles.slice(0, plan.count)
  const hidden = tiles.slice(plan.count)
  const share = plan.count === 3 ? '33%' : plan.count === 2 ? '50%' : '100%'
  const hiddenLine =
    hidden.length > 0 &&
    lineRow(el, [
      { t: fit(width, [hidden.map(t => `${t.captions[0]} ${t.plain}`).join(' · '), hidden.map(t => `${t.captions[t.captions.length - 1]} ${t.plain}`).join(' · ')]), tone: 'muted' },
    ])
  if (Svg) {
    const art = tilesSvg(
      drawingWidth(width + 1),
      shown.map(t => ({ face: t.plain, captions: t.captions, tone: t.tone })),
      shown.map(t => `${t.captions[0]} ${t.plain}`).join(', '),
    )
    return (
      <Box flexDirection="column" width="100%">
        <Svg source={art.source} alt={art.alt} />
        {hiddenLine}
      </Box>
    )
  }
  return (
    <Box flexDirection="column" width="100%">
      <Box flexDirection="row" columnGap={1} width="100%">
        {shown.map(t => {
          const face = tileFace(t.numerals, t.plain, plan.inner)
          return (
            <Box key={`tile-${t.id}`} flexDirection="column" alignItems="center" width={share} flexShrink={1} borderStyle="round" borderColor={COLORS.hair}>
              {face.kind === 'big' ? (
                <Box flexDirection="column" alignItems="flex-start">
                  {face.rows.map(row => (
                    <Text bold color={COLORS[t.tone]}>
                      {row}
                    </Text>
                  ))}
                </Box>
              ) : (
                <Text bold color={COLORS[t.tone]}>
                  {face.text}
                </Text>
              )}
              <Text color={COLORS.muted}>{fit(plan.inner, t.captions)}</Text>
            </Box>
          )
        })}
      </Box>
      {hiddenLine}
    </Box>
  )
}

function kindRows(el: El, width: number, kinds: Record<Kind, number>, hours: Record<Kind, number>, Svg?: SvgEl) {
  const isWide = width >= 46
  const names = isWide ? KIND_LABEL : KIND_SHORT
  // only what this stretch holds: a coder is not shown an empty Emails row
  const shown = shownKinds(kinds)
  const max = Math.max(1, ...shown.map(k => kinds[k]))
  const cw = String(max).length
  const hourTexts = shown.map(k => `${hoursText(hours[k])}h`)
  const hw = Math.max(1, ...hourTexts.map(t => t.length))
  const showHours = width >= 30
  if (Svg) {
    const art = barsSvg(
      drawingWidth(width + 1),
      shown.map((k, i) => ({
        label: names[k],
        count: kinds[k],
        max,
        tails: showHours ? [String(kinds[k]), hourTexts[i] ?? ''] : [String(kinds[k])],
        tone: KIND_TONE[k],
      })),
      shown.map(k => `${KIND_LABEL[k]} ${kinds[k]}`).join(', '),
    )
    return [<Svg source={art.source} alt={art.alt} />]
  }
  return shown.map((k, i) =>
    lineRow(
      el,
      barRow(width, isWide ? 16 : 8, {
        label: names[k],
        count: kinds[k],
        max,
        tail: showHours ? `${padStart(String(kinds[k]), cw)}  ${padStart(hourTexts[i] ?? '', hw)}` : padStart(String(kinds[k]), cw),
        tone: KIND_TONE[k],
      }),
    ),
  )
}

const MODEL_ROWS = 5

function modelRows(el: El, width: number, models: Record<string, number>, Svg?: SvgEl) {
  const sorted = Object.entries(models).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
  const top3 = sorted.slice(0, MODEL_ROWS)
  const rest = sorted.slice(MODEL_ROWS).reduce((n, [, c]) => n + c, 0)
  const rows: [string, number][] = rest > 0 ? [...top3, ['Others', rest]] : top3
  const max = Math.max(1, ...rows.map(r => r[1]))
  const cw = String(max).length
  if (Svg) {
    const art = barsSvg(
      drawingWidth(width + 1),
      rows.map(([name, count]) => ({ label: name, count, max, tails: [String(count)], tone: 'gold' as const })),
      rows.map(([name, count]) => `${name} ${count}`).join(', '),
    )
    return [<Svg source={art.source} alt={art.alt} />]
  }
  const labelWidth = Math.min(16, Math.max(...rows.map(r => strWidth(r[0]))))
  return rows.map(([name, count]) => lineRow(el, barRow(width, labelWidth, { label: name, count, max, tail: padStart(String(count), cw), tone: 'gold' })))
}

// ── The pane ─────────────────────────────────────────────────────────────

/** The pane's whole body for the model. `el` is the terminal's table. */
export function drawPane(el: El, m: Model, a: Actions) {
  const { Box, Text } = el
  // one cell is kept back: a row the surface lays out narrower than it reported is clipped, not wrapped
  const width = Math.max(20, m.width - 1)

  const days = daysFor(m.tab, m.now)
  const totals = totalsFor(m.days, days.map(keyOf))
  const header = (
    <Box flexDirection="column" width="100%">
      {top(el)}
      {blank(el)}
      <Box flexDirection="row" flexWrap="wrap" columnGap={1}>
        {TABS.map(t =>
          chip(el, { key: `tab-${t.tab}`, label: TAB_NAME[t.tab], isMain: t.tab === m.tab, hotkey: t.hotkey, onPress: () => a.pickTab(t.tab) }),
        )}
      </Box>
      {blank(el)}
      {titleBar(el, width, stretchName(m.tab, m.now), describeDays(days))}
      {blank(el)}
    </Box>
  )

  if (totals.tasks === 0) {
    return (
      <Box flexDirection="column" width="100%">
        {header}
        <Box flexDirection="column" width="100%" borderStyle="round" borderColor={COLORS.hair} paddingX={1}>
          <Text color={COLORS.text} wrap="wrap">
            {`Nothing finished yet ${sinceWords(m.tab)}. Your first finished task shows up here.`}
          </Text>
        </Box>
      </Box>
    )
  }

  const est = estimate(totals.kinds, m.settings)
  const hours = {} as Record<Kind, number>
  for (const k of KINDS) hours[k] = est.byKind[k].hours
  const bars = chartFor(m.tab, m.days, m.now)
  const summary = summaryFor(m.tab, m.days, m.now)
  const chart = m.Svg
    ? (() => {
        const { Svg } = m
        const art = chartSvg(drawingWidth(width + 1), bars, `${m.tab === 'year' ? 'Tasks per month' : 'Tasks per day'}: ${bars.map(b => b.value).join(', ')}`)
        return [<Svg source={art.source} alt={art.alt} />]
      })()
    : (() => {
        const plan = chartPlan(bars, width)
        return [...plan.rows.map(line => lineRow(el, line)), lineRow(el, [{ t: plan.axis, tone: 'muted' as const }])]
      })()
  const note = fit(width, [
    `Hours and dollars are estimates: minutes per task at $${m.settings.rate} an hour. /report settings changes them.`,
    `Estimates: minutes per task at $${m.settings.rate} an hour. /report settings changes them.`,
    `Estimates only. /report settings changes them.`,
    'Estimates only.',
  ])

  return (
    <Box flexDirection="column" width="100%">
      {header}
      {tilesBlock(el, width, totals.tasks, est.hours, est.dollars, m.Svg)}
      {lineRow(el, [{ t: note, tone: 'muted' }])}
      {blank(el)}
      {heading(el, width, 'Where the time went', 'estimate')}
      {kindRows(el, width, totals.kinds, hours, m.Svg)}
      {blank(el)}
      {heading(el, width, 'Who did the work')}
      {modelRows(el, width, totals.models, m.Svg)}
      {blank(el)}
      {heading(el, width, 'Tasks', m.tab === 'year' ? 'per month' : 'per day')}
      {chart}
      {blank(el)}
      {lineRow(el, [{ t: fit(width, [summary.text, summary.short]), tone: summary.isGood ? 'green' : 'muted' }])}
    </Box>
  )
}

